const response = $input.first().json.content;
try {
  // Use regex to clean up potential markdown formatting if Gemini includes it
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  const jsonStr = jsonMatch ? jsonMatch[0] : response;
  const parsed = JSON.parse(jsonStr);
  return {
    kategorija: parsed.kategorija,
    prioritet_skor: parseInt(parsed.prioritet_skor) || 0,
    obrazlozenje: parsed.obrazlozenje,
    sledeca_akcija: parsed.sledeca_akcija
  };
} catch (e) {
  return {
    kategorija: "Nepoznato",
    prioritet_skor: 0,
    obrazlozenje: "Greška pri parsiranju AI odgovora.",
    sledeca_akcija: "Ručna provera"
  };
}
